import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
forms={
 't^q A^p exp(-kA)': lambda p: t**p[5]*A**p[6]*np.exp(-p[7]*A),
 't^q A^p exp(-kt)': lambda p: t**p[5]*A**p[6]*np.exp(-p[7]*t),
 't^q A^p exp(-kAt)': lambda p: t**p[5]*A**p[6]*np.exp(-p[7]*A*t),
 'exp(-kA) sqrt t (1+qA)^p': lambda p: np.sqrt(t)*np.exp(-p[7]*A)*(1+p[6]*A)**p[5],
}
for name,g in forms.items():
    best=None
    for s in range(30):
        rng=np.random.default_rng(300+s)
        p0=[rng.normal(-4,1),rng.normal(-0.6,0.2),rng.uniform(1,3),rng.normal(2.8,0.3),rng.normal(0,2),rng.uniform(-0.5,2),rng.uniform(-1,2),rng.uniform(0,1.5)]
        def model(p):
            return p[0]*np.sqrt(t)+p[1]*np.log(1+p[2]*A)*t+p[3]*np.log(1+A)**2+p[4]*g(p)
        try:
            with np.errstate(all='ignore'):
                r=least_squares(lambda p: model(p)-y, p0, max_nfev=3000)
            if np.all(np.isfinite(r.fun)) and (best is None or r.cost<best.cost): best=r
        except Exception: pass
    print(name, np.mean(best.fun**2)/np.var(y), np.round(best.x,4))

